// ───────────────────────────────────────────── Printables ─────────────────────────────────────────────
function seeded(seed: number) { let s = seed >>> 0; return () => { s = (s * 1664525 + 1013904223) >>> 0; return s / 4294967296; }; }
export function wordSearch(words: string[], size: number, seed: number): { grid: string[][]; placed: { word: string; row: number; col: number; dr: number; dc: number }[] } {
  const rnd = seeded(seed);
  const grid: string[][] = Array.from({ length: size }, () => Array.from({ length: size }, () => ""));
  const dirs: [number, number][] = [[0, 1], [1, 0], [1, 1], [-1, 1]];
  const placed: { word: string; row: number; col: number; dr: number; dc: number }[] = [];
  for (const raw of [...words].sort((a, b) => b.length - a.length)) {
    const word = raw.toUpperCase().replace(/[^A-Z]/g, "");
    let done = false;
    for (let attempt = 0; attempt < 500 && !done; attempt++) {
      const [dr, dc] = dirs[Math.floor(rnd() * dirs.length)] ?? [0, 1];
      const row = Math.floor(rnd() * size), col = Math.floor(rnd() * size);
      const endR = row + dr * (word.length - 1), endC = col + dc * (word.length - 1);
      if (endR < 0 || endR >= size || endC < 0 || endC >= size) continue;
      let ok = true;
      for (let i = 0; i < word.length; i++) { const ch = grid[row + dr * i]?.[col + dc * i]; if (ch && ch !== word[i]) { ok = false; break; } }
      if (!ok) continue;
      for (let i = 0; i < word.length; i++) { const line = grid[row + dr * i]; if (line) line[col + dc * i] = word[i] ?? ""; }
      placed.push({ word, row, col, dr, dc });
      done = true;
    }
    if (!done) throw new Error(`word search: could not place ${word}`);
  }
  const letters = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
  for (const line of grid) for (let c = 0; c < size; c++) if (!line[c]) line[c] = letters[Math.floor(rnd() * 26)] ?? "A";
  return { grid, placed };
}
const esc = (s: string) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
const gridHtml = (grid: string[][], cell = 30) => `<table style="border-collapse:collapse;margin:12px auto;font-family:Helvetica,Arial,sans-serif;font-size:${Math.round(cell * 0.6)}px">${grid.map((row) => `<tr>${row.map((ch) => `<td style="border:1px solid #9CA3AF;width:${cell}px;height:${cell}px;text-align:center">${ch}</td>`).join("")}</tr>`).join("")}</table>`;

